package vn.edu.hunre.nhom11.carrental.identity.api;
import java.security.Principal; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
import vn.edu.hunre.nhom11.carrental.identity.repository.UserRepository; import vn.edu.hunre.nhom11.carrental.shared.exception.ApiException;
@RestController @RequestMapping("/api/users")
public class UserController { private final UserRepository users; public UserController(UserRepository u){users=u;} @GetMapping @PreAuthorize("hasRole('ADMIN')") public Object all(){return users.findAll();} @PatchMapping("/{id}/lock") @PreAuthorize("hasRole('ADMIN')") public Object lock(@PathVariable Long id){var u=users.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Không tìm thấy người dùng"));u.setLocked(!u.isLocked());return users.save(u);} @GetMapping("/me") public Object me(Principal p){return profile(find(p));} @PutMapping("/me") public Object update(Principal p,@RequestBody ProfileUpdate r){var u=find(p);if(r.name()==null||r.name().isBlank()||r.phone()==null||r.phone().isBlank()||r.address()==null||r.address().isBlank())throw new ApiException(HttpStatus.BAD_REQUEST,"Vui lòng điền đầy đủ thông tin cá nhân");u.setName(r.name().trim());u.setPhone(r.phone().trim());u.setAddress(r.address().trim());users.save(u);return profile(u);} private vn.edu.hunre.nhom11.carrental.identity.domain.User find(Principal p){return users.findByEmailIgnoreCase(p.getName()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Không tìm thấy người dùng"));}private Profile profile(vn.edu.hunre.nhom11.carrental.identity.domain.User u){return new Profile(u.getId(),u.getName(),u.getEmail(),u.getPhone(),u.getAddress(),u.getRole().name());}record Profile(Long id,String name,String email,String phone,String address,String role){}record ProfileUpdate(String name,String phone,String address){} }
